// V18.2 : le mode automatique interroge la BnF (dépôt légal), qui filtre
// réellement par année de publication — contrairement à Google Books, dont le
// "newest" ramenait des livres de 1990-2010 (V18/V18.1) voire d'avant 1990 (V17).
// Les recherches explicites (Telegram /recherche, /livre) gardent Google Books.
const cfg = $('CONFIG - thèmes et chaîne').first().json;
const source = String(cfg.source || 'automatique').toLowerCase();
const chaine = String(cfg.chaine || 'Impacteur Frexit');

if (source !== 'automatique') {
  const q = String(cfg.recherche || 'histoire politique');
  return [0,20,40,60,80].map(startIndex => ({ json: { moteur: 'google', startIndex, q }, pairedItem: { item: 0 } }));
}

const annee = new Date().getFullYear();
const themesParChaine = {
  'Impacteur Afrique': ['Afrique', 'Sahel', 'panafricanisme', 'Afrique politique', 'Afrique histoire', 'Afrique économie', 'Maghreb'],
  'Impacteur Frexit': ['politique', 'histoire politique', 'Union européenne', 'souveraineté', 'géopolitique', 'diplomatie', 'économie politique']
};
const themes = themesParChaine[chaine] || themesParChaine['Impacteur Frexit'];

// Rotation quotidienne : 5 des 7 thèmes par jour, décalés pour tout couvrir.
const jour = Math.floor(Date.now() / 86400000);
const requetes = [];
for (let i = 0; i < 5; i++) {
  const theme = themes[(jour * 5 + i) % themes.length];
  const cql = 'bib.subject all "' + theme + '" and bib.publicationdate >= "' + (annee - 1) + '" and bib.language any "fre"';
  requetes.push(cql);
}
return requetes.map(cql => ({ json: { moteur: 'bnf', cql, maximumRecords: 20, startRecord: 1 }, pairedItem: { item: 0 } }));

const cfg=$('CONFIG - thèmes et chaîne').first().json;
const tous=$input.all().map(x=>x.json);
const souhaite=Math.max(1,Math.min(5,Number(cfg.max_livres)||3));
// Limiter la charge du LLM : assez de choix, sans lui envoyer 20 fiches d'un coup.
const limite=Math.min(12,Math.max(6,souhaite*4));
const candidats=tous.slice(0,limite);
return [{json:{
  candidats,
  candidats_avant_tri:tous.length,
  candidats_envoyes_au_tri:candidats.length
},pairedItem:candidats.map((_,i)=>({item:i}))}];

const reponse=$input.first().json;
const cfg=$('CONFIG - thèmes et chaîne').first().json;
const base=$('PREPARER SELECTION EDITORIALE').first().json.candidats || [];

const sortieSansResultat=(raison,warning='')=>[{json:{
  _no_result:true,
  _no_result_stage:'SELECTION_EDITORIALE',
  _no_result_reason:raison,
  _editorial_warning:warning,
  chaine:String(cfg.chaine||''),
  recherche:String(cfg.recherche||''),
  source:String(cfg.source||'automatique'),
  telegram_chat_id:String(cfg.telegram_chat_id||'')
}}];

if(!base.length){
  return sortieSansResultat('Aucun candidat n’a été transmis au tri éditorial.');
}

// V16.4 : ces deux cas sont de vrais incidents techniques, pas un résultat métier normal.
if(reponse.stop_reason==='max_tokens'){
  throw new Error('TRI_EDITORIAL_TECHNIQUE : réponse Claude tronquée (max_tokens).');
}

const txt=(reponse.content||[])
  .map(x=>x.text||'')
  .join('\n')
  .trim()
  .replace(/^```(?:json)?\s*/i,'')
  .replace(/\s*```$/,'');

let parsed;
try{
  parsed=JSON.parse(txt);
}catch(e){
  throw new Error('TRI_EDITORIAL_TECHNIQUE : JSON Claude invalide.');
}

if(!Array.isArray(parsed.evaluations)){
  throw new Error('TRI_EDITORIAL_TECHNIQUE : liste evaluations absente.');
}

const map=new Map(base.map(x=>[String(x.cle_unique||''),x]));
const seen=new Set();
const acceptes=[];
let invalides=0;

for(const e of parsed.evaluations){
  if(!e || typeof e!=='object'){ invalides++; continue; }
  const cle=String(e.cle_unique||'');
  if(!cle || !map.has(cle) || seen.has(cle)){ invalides++; continue; }

  if(
    typeof e.pertinent!=='boolean' ||
    typeof e.personne_physique!=='boolean' ||
    typeof e.francais!=='boolean' ||
    typeof e.raison!=='string' ||
    !e.raison.trim()
  ){
    invalides++;
    seen.add(cle);
    continue;
  }

  seen.add(cle);

  if(e.pertinent===true && e.personne_physique===true && e.francais===true){
    acceptes.push({
      json:{
        ...map.get(cle),
        raison_selection:e.raison.trim()
      },
      pairedItem:{item:0}
    });
  }
}

const missing=base
  .map(x=>String(x.cle_unique||''))
  .filter(cle=>cle && !seen.has(cle));

const coverage=base.length ? seen.size/base.length : 0;
const lowCoverage=coverage<0.5;
const details=[];
if(missing.length){
  details.push(...missing.map(cle=>'EVALUATION_INCOMPLETE : candidat '+cle+' non évalué, écarté par défaut.'));
}
if(invalides){
  details.push('EVALUATION_INVALIDE : '+invalides+' évaluation(s) incomplète(s), inconnue(s) ou dupliquée(s) ignorée(s).');
}
if(lowCoverage){
  details.push('TRI_EDITORIAL_INCOMPLET : seulement '+seen.size+'/'+base.length+' candidat(s) correctement évalué(s).');
}
const warning=details.join(' | ');
const max=Math.max(1,Math.min(5,Number(cfg.max_livres)||3));

if(!acceptes.length){
  let raison='Aucun candidat n’a été retenu par le tri éditorial ('+seen.size+'/'+base.length+' candidat(s) évalué(s)).';
  if(warning) raison+=' '+warning;
  return sortieSansResultat(raison, lowCoverage ? warning : '');
}

return acceptes.slice(0,max).map(x=>({
  json:{
    ...x.json,
    tri_editorial_evalues:seen.size,
    tri_editorial_total:base.length,
    tri_editorial_couverture:coverage,
    tri_editorial_avertissement:warning,
    _editorial_warning:lowCoverage ? warning : ''
  },
  pairedItem:x.pairedItem
}));

