function norm(s){return String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();}
function signalDeces(value){
 let s=norm(value)
  .replace(/\baucune mention de deces(?:\s+relevee)?\b/g,'')
  .replace(/\baucun (?:signe|signal|indice) de deces\b/g,'')
  .replace(/\babsence de mention de deces\b/g,'')
  .replace(/\bpas de mention de deces\b/g,'')
  .replace(/\baucune source n.(?:indique|evoque|mentionne|signale)[^.;]{0,40}\bdeces\b/g,'')
  .replace(/\bn.(?:indique|evoque|mentionne|signale)\s+(?:pas\s+|aucun\s+)?(?:de\s+|d.un\s+)?deces\b/g,'')
  .replace(/\baucun deces\b/g,'');
 return /\b(decede(?:e|s|es)?|deces|mort(?:e|s|es)?|died|deceased|obituary|necrologie)\b/.test(s);
}
// V18.3 : le signal deterministe ne compte que si le mot de deces apparait
// dans un resultat citant le NOM DE FAMILLE de l'auteur ("mort" a propos de
// n'importe qui ne bloque plus tout), et il n'ecrase plus la conclusion de
// Claude : il envoie en A_VERIFIER_DECES (deblocable via /debloquer), le
// blocage definitif restant reserve a une conclusion BLOQUER de Claude.
return $input.all().map((item,i)=>{
 const base=$('PREPARER CONTROLE DECES CLAUDE').itemMatching(i).json;
 const nomFamille=norm(String(base.auteur||'').trim().split(/\s+/).pop());
 const deterministic=(base.resultats_controle_deces||[]).some(r=>{
   const texte=norm(String(r.titre||'')+' '+String(r.description||''));
   return nomFamille.length>=3 && texte.includes(nomFamille) && signalDeces(texte);
 });
 let parsed={decision:'DOUTE',raison:'Réponse du contrôle biographique invalide.'};
 try{
   const txt=(item.json.content||[]).map(x=>x.text||'').join('\n').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
   parsed=JSON.parse(txt);
 }catch(e){}
 const decision=String(parsed.decision||'DOUTE').trim().toUpperCase();
 let statut_controle='CONTINUER';
 let statut='A_VERIFIER';
 let raison=String(parsed.raison||'').slice(0,800);
 if(decision==='BLOQUER'){
   statut_controle='BLOQUE';
   statut='BLOQUE_ELIGIBILITE';
 } else if(decision!=='CONTINUER' || deterministic){
   statut_controle='DOUTE';
   statut='A_VERIFIER_DECES';
   if(decision==='CONTINUER' && deterministic){
     raison=(raison?raison+' — ':'')+'Garde-fou : un résultat citant le nom de l\'auteur contient un terme de décès ; vérification humaine puis /debloquer si faux positif.';
   }
 }
 return {json:{
   ...base,
   controle_deces_decision:statut_controle,
   controle_deces_raison:raison.slice(0,800),
   signal_deces_precoce:statut_controle!=='CONTINUER',
   statut
 },pairedItem:{item:i}};
});

