function norm(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function emails(text){return [...String(text||'').matchAll(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi)].map(m=>m[0].toLowerCase());}
function generic(email){
 const local=String(email).split('@')[0].replace(/[._-]/g,'');
 return /^(presse|press|media|medias|communication|communications|contact|info|servicepresse|relationspresse|rp|marketing|publicite|publicity|editorial|edition|editions|auteur|auteurs|author|authors)$/.test(local);
}
return $input.all().map((item,i)=>{
 const j={...item.json};
 const a=norm(j.auteur);
 const nom=(a.split(/\s+/).filter(Boolean).pop()||'');
 let direct=false,generique=false;
 for(const r of (j.resultats_auteur||[])){
  const contexte=norm((r.titre||'')+' '+(r.description||'')+' '+(r.url||''));
  for(const e of emails((r.description||'')+' '+(r.titre||''))){
    if(generic(e)) generique=true;
    else if((a.length>4&&contexte.includes(a))||(nom.length>3&&contexte.includes(nom))) direct=true;
  }
 }
 return {json:{...j,contact_direct_deja_trouve:direct,contact_generique_deja_trouve:generique,besoin_contact_direct:!direct},pairedItem:{item:i}};
});

