   titre:r.title||'',url:r.url||'',description:r.description||'',origine:'contact_direct'
 }));
 return {json:{...base,resultats_auteur:[...(base.resultats_auteur||[]),...add],recherche_contact_direct_effectuee:true},pairedItem:{item:i}};
});

const publicDomains=new Set(['gmail.com','hotmail.com','outlook.com','yahoo.com','proton.me','icloud.com','live.com']);
const out=[];
for(let i=0;i<$input.all().length;i++){
 const r=$input.all()[i].json;
 const statut=String(r.statut||'').trim().toUpperCase();
 const validation=String(r.validation_contact||'').trim().toUpperCase();
 const email=String(r.email_contact||'').trim().toLowerCase();
 const src=String(r.source_contact_validee||'').trim();
 const domain=email.split('@')[1]||'';
 const type=String(r.type_contact||'').trim().toLowerCase();
 if(statut!=='APPROUVE'||validation!=='OUI'||!publicDomains.has(domain)||!/^https:\/\//i.test(src)||
    !/^\S+@\S+\.\S+$/.test(email)||!['auteur','auteur_direct','editeur','presse_generique','service_presse'].includes(type)||
    !String(r.cle_unique||'').trim()||String(r.draft_id||'').trim())continue;
 const old=String(r.informations_a_verifier||'');
 const note='REJET_DOMAINE_GRAND_PUBLIC : '+domain+' bloqué par défaut. Pour une adresse officiellement publiée et validée humainement, remettre statut=APPROUVE et validation_contact=OUI_EXCEPTION.';
 const infos=old.includes('REJET_DOMAINE_GRAND_PUBLIC')?old:(old?old+' | '+note:note);
 out.push({json:{
   cle_unique:String(r.cle_unique).trim(),
   statut:'REJETE_DOMAINE_GRAND_PUBLIC',
   validation_contact:'NON',
   informations_a_verifier:infos,
   derniere_mise_a_jour:new Date().toISOString()
 },pairedItem:{item:i}});
}
return out;

function norm(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();}
function signalDeces(value){
 let s=norm(value)
  .replace(/\baucune mention de deces(?:\s+relevee)?\b/g,'')
  .replace(/\baucun (?:signe|signal|indice) de deces\b/g,'')
  .replace(/\babsence de mention de deces\b/g,'')
  .replace(/\bpas de mention de deces\b/g,'');
 return /\b(decede(?:e|s|es)?|deces|mort(?:e|s|es)?|died|deceased|obituary|necrologie)\b/.test(s);
}
const known=new Set(['guy bourde','eric duhamel']);
const out=[];
for(let i=0;i<$input.all().length;i++){
 const r=$input.all()[i].json;
 const a=norm(r.auteur);
 const alert=String(r.informations_a_verifier||'');
 const explicit=known.has(a)||signalDeces(alert);
 if(!explicit||!String(r.cle_unique||'').trim())continue;
 if(String(r.statut||'').trim().toUpperCase()==='NE_PAS_CONTACTER')continue;
 const note='CORRECTION_SECURITE_DECES_V16 : auteur marqué NE_PAS_CONTACTER avant toute création de brouillon.';
 const infos=alert.includes('CORRECTION_SECURITE_DECES_V16')?alert:(alert?alert+' | '+note:note);
 out.push({json:{
   cle_unique:String(r.cle_unique).trim(),
   statut:'NE_PAS_CONTACTER',
   validation_contact:'NON',
   informations_a_verifier:infos,
   derniere_mise_a_jour:new Date().toISOString()
 },pairedItem:{item:i}});
}
return out;

const input = $input.first().json;
const msg = input.message || {};
const raw = String(msg.text || '').trim();
const chatId = msg.chat?.id;
const userId = msg.from?.id;

if (!raw || chatId === undefined || userId === undefined) return [];

const store = $getWorkflowStaticData('global');
const CLAIM_CODE = 'X2VF3EJ19C';
const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const html = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const cleaned = raw.replace(/^\/([a-zA-Z_]+)@\w+/, '/$1').trim();
const low = norm(cleaned);

// Première prise de contrôle : le premier utilisateur qui connaît le code devient l'unique propriétaire.
if (!store.telegram_owner_user_id) {
  if (low === '/claim ' + CLAIM_CODE.toLowerCase()) {
    store.telegram_owner_user_id = String(userId);
    store.telegram_chat_id = String(chatId);
    return [{json:{
      route:'reply', action:'claim', source:'telegram',
      chat_id:String(chatId), user_id:String(userId),
      telegram_message:'✅ Bot Impacteur associé à ce compte Telegram.\n\nUser ID : ' + html(userId) + '\nChat ID : ' + html(chatId) + '\n\nEnvoie /aide pour voir les commandes.'
    }}];
  }
  return [{json:{
    route:'reply', action:'locked', source:'telegram',
    chat_id:String(chatId), user_id:String(userId),
    telegram_message:'🔒 Bot non encore associé à son propriétaire. Utilise la commande /claim fournie lors de l’installation.'
  }}];
}

// Après la prise de contrôle, ignorer silencieusement tout autre utilisateur.
if (String(userId) !== String(store.telegram_owner_user_id)) return [];

store.telegram_chat_id = String(chatId);

const help = `Commandes disponibles :

/rapport
/averifier
/problemes
/brouillons
/id

/recherche frexit 5 histoire politique
/recherche afrique 5 souveraineté monétaire

/livre frexit | Titre du livre | Nom de l’auteur
/livre afrique | Titre du livre | Nom de l’auteur

Tu peux aussi écrire par exemple :
« cherche 4 livres sur le Sahel pour Afrique »
« prospecte le livre "Titre" de Auteur pour Frexit »

La prospection automatique quotidienne continue indépendamment de Telegram.
Pour lever un faux positif décès après vérification humaine :
/debloquer CLE_UNIQUE vivant
Cette commande ne fonctionne que pour un dossier A_VERIFIER_DECES et le remet en A_RETRAITER.

Aucun email n’est envoyé automatiquement : la branche Gmail reste une création de brouillon après validation.`;

if (['/start','/aide','aide','menu','commandes'].includes(low)) {
  return [{json:{route:'reply',action:'aide',source:'telegram',chat_id:String(chatId),user_id:String(userId),telegram_message:help}}];
}

if (low === '/id' || low === 'mon id' || low === 'id') {
  return [{json:{
    route:'reply',action:'id',source:'telegram',
    chat_id:String(chatId),user_id:String(userId),
    telegram_message:'User ID : ' + html(userId) + '\nChat ID : ' + html(chatId)
  }}];
}

// Déblocage humain sécurisé d'un faux positif décès.
let d = cleaned.match(/^\/debloquer\s+(\S+)\s+vivant$/i);
if (d) {
  return [{json:{
    route:'debloquer',action:'debloquer',source:'telegram',
    chat_id:String(chatId),user_id:String(userId),
    cle_unique:d[1].trim()
  }}];
}
if (/^\/debloquer\b/i.test(cleaned)) {
  return [{json:{
    route:'reply',action:'debloquer_usage',source:'telegram',
    chat_id:String(chatId),user_id:String(userId),
    telegram_message:'Usage sécurisé : /debloquer CLE_UNIQUE vivant\n\nLa commande est réservée aux dossiers A_VERIFIER_DECES vérifiés humainement.'
  }}];
}

if (low === '/rapport' || /\b(rapport|bilan|resume du jour|résumé du jour)\b/.test(low)) {
  return [{json:{route:'info',action:'rapport',source:'telegram',chat_id:String(chatId),user_id:String(userId)}}];
}
if (low === '/averifier' || /\b(a verifier|à verifier|a vérifier|à vérifier|en attente de verification|en attente de vérification)\b/.test(low)) {
  return [{json:{route:'info',action:'averifier',source:'telegram',chat_id:String(chatId),user_id:String(userId)}}];
}
if (low === '/problemes' || /\b(problemes|problèmes|bloques|bloqués|erreurs)\b/.test(low)) {
  return [{json:{route:'info',action:'problemes',source:'telegram',chat_id:String(chatId),user_id:String(userId)}}];
}
if (low === '/brouillons' || /\bbrouillons?\b/.test(low)) {
  return [{json:{route:'info',action:'brouillons',source:'telegram',chat_id:String(chatId),user_id:String(userId)}}];
}

// /recherche frexit 5 histoire politique
let m = cleaned.match(/^\/recherche\s+(afrique|frexit)\s+(\d{1,2})\s+(.+)$/i);
if (m) {
  const n = Math.max(1, Math.min(10, Number(m[2]) || 3));
  const chaine = m[1].toLowerCase() === 'afrique' ? 'Impacteur Afrique' : 'Impacteur Frexit';
  const sujet = m[3].trim();
  return [{json:{
    route:'mission',action:'recherche',mode:'telegram_recherche',source:'telegram',
    chat_id:String(chatId),user_id:String(userId),
    recherche:sujet,chaine,max_livres:n,
    telegram_message:'🔎 Recherche lancée : ' + html(sujet) + '\nChaîne : ' + html(chaine) + '\nMaximum : ' + n + ' livre(s).'
  }}];
}

// /livre frexit | Titre | Auteur
m = cleaned.match(/^\/livre\s+(afrique|frexit)\s*\|\s*(.+?)\s*\|\s*(.+)$/i);
if (m) {
  const chaine = m[1].toLowerCase() === 'afrique' ? 'Impacteur Afrique' : 'Impacteur Frexit';
  const titre = m[2].trim();
  const auteur = m[3].trim();
  const q = 'intitle:"' + titre.replace(/"/g,'') + '" inauthor:"' + auteur.replace(/"/g,'') + '"';
  return [{json:{
    route:'mission',action:'livre',mode:'telegram_livre',source:'telegram',
    chat_id:String(chatId),user_id:String(userId),
    recherche:q,chaine,max_livres:1,titre_demande:titre,auteur_demande:auteur,
    telegram_message:'📚 Prospection ciblée lancée.\nLivre : ' + html(titre) + '\nAuteur : ' + html(auteur) + '\nChaîne : ' + html(chaine)
  }}];
}

// Forme naturelle : cherche 4 livres sur le Sahel pour Afrique
m = cleaned.match(/^(?:cherche|recherche|prospecte)\s+(\d{1,2})\s+(?:livres?|auteurs?)\s+(?:sur|concernant|a propos de|à propos de)\s+(.+?)\s+pour\s+(afrique|frexit)$/i);
if (m) {
  const n = Math.max(1, Math.min(10, Number(m[1]) || 3));
  const sujet = m[2].trim();
  const chaine = m[3].toLowerCase() === 'afrique' ? 'Impacteur Afrique' : 'Impacteur Frexit';
  return [{json:{
    route:'mission',action:'recherche',mode:'telegram_recherche',source:'telegram',
    chat_id:String(chatId),user_id:String(userId),
    recherche:sujet,chaine,max_livres:n,
    telegram_message:'🔎 Recherche lancée : ' + html(sujet) + '\nChaîne : ' + html(chaine) + '\nMaximum : ' + n + ' livre(s).'
  }}];
}

// Forme naturelle : prospecte le livre "Titre" de Auteur pour Frexit
m = cleaned.match(/^prospecte\s+(?:le\s+)?livre\s+["“]?(.+?)["”]?\s+de\s+(.+?)\s+pour\s+(afrique|frexit)$/i);
if (m) {
  const titre = m[1].trim().replace(/^["“]|["”]$/g,'');
  const auteur = m[2].trim();
  const chaine = m[3].toLowerCase() === 'afrique' ? 'Impacteur Afrique' : 'Impacteur Frexit';
  const q = 'intitle:"' + titre.replace(/"/g,'') + '" inauthor:"' + auteur.replace(/"/g,'') + '"';
  return [{json:{
    route:'mission',action:'livre',mode:'telegram_livre',source:'telegram',
    chat_id:String(chatId),user_id:String(userId),
    recherche:q,chaine,max_livres:1,titre_demande:titre,auteur_demande:auteur,
    telegram_message:'📚 Prospection ciblée lancée.\nLivre : ' + html(titre) + '\nAuteur : ' + html(auteur) + '\nChaîne : ' + html(chaine)
  }}];
}

return [{json:{
  route:'reply',action:'inconnu',source:'telegram',
  chat_id:String(chatId),user_id:String(userId),
  telegram_message:'Je n’ai pas reconnu la demande.\n\n' + help
}}];

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);
const req = $('TELEGRAM - analyser message').first().json;
const action = String(req.action || '');
const chat_id = String(req.chat_id || '');

const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const val = s => String(s ?? '').trim();
const upper = s => val(s).toUpperCase();
const d = x => {
  const t = Date.parse(val(x));
  return Number.isFinite(t) ? t : 0;
};
rows.sort((a,b)=>d(b.derniere_mise_a_jour)-d(a.derniere_mise_a_jour));

const line = r => {
  const a = esc(val(r.auteur) || 'Auteur inconnu');
  const l = esc(val(r.livre) || 'Livre inconnu');
  const s = esc(val(r.statut) || 'SANS_STATUT');
  return `• ${a} — ${l}\n  Statut : ${s}`;
};

let text = '';
if (action === 'rapport') {
  const now = Date.now(), day = 24*60*60*1000;
  const recent = rows.filter(r => d(r.derniere_mise_a_jour) && now-d(r.derniere_mise_a_jour) <= day);
  const count = status => rows.filter(r => upper(r.statut) === status).length;
  const drafts = rows.filter(r => val(r.draft_id) || upper(r.statut)==='BROUILLON_CREE').length;
  text =
`📊 Rapport prospection

Total dossiers : ${rows.length}
Mis à jour sur 24 h : ${recent.length}
À vérifier : ${count('A_VERIFIER')}
YouTube à qualifier : ${count('YOUTUBE_A_QUALIFIER')}
À corriger : ${count('A_CORRIGER')}
Bloqués : ${rows.filter(r => upper(r.statut).startsWith('BLOQUE')).length}
Approuvés : ${count('APPROUVE')}
Brouillons créés : ${drafts}

Dernières activités :
${recent.slice(0,6).map(line).join('\n') || 'Aucune activité sur les dernières 24 h.'}`;
} else if (action === 'averifier') {
  const list = rows.filter(r => upper(r.statut)==='A_VERIFIER' || (upper(r.validation_contact)!=='OUI' && upper(r.statut)==='APPROUVE'));
  text = `🔎 Dossiers à vérifier (${list.length})\n\n` + (list.slice(0,10).map(line).join('\n\n') || 'Aucun dossier en attente.');
} else if (action === 'problemes') {
  const list = rows.filter(r => upper(r.statut).startsWith('BLOQUE') || ['A_CORRIGER','A_VERIFIER_DECES','REJETE_DOMAINE_GRAND_PUBLIC','NE_PAS_CONTACTER'].includes(upper(r.statut)) || /BLOCAGE_|REJET_DOMAINE_GRAND_PUBLIC/i.test(val(r.informations_a_verifier)));
  text = `⚠️ Dossiers problématiques (${list.length})\n\n` + (list.slice(0,10).map(r => {
    const base=line(r);
    let why=val(r.informations_a_verifier);
    if (why.length>300) why=why.slice(0,300)+'…';
    return base + (why ? '\n  À vérifier : '+esc(why) : '');
  }).join('\n\n') || 'Aucun dossier problématique.');
} else if (action === 'brouillons') {
  const list = rows.filter(r => val(r.draft_id) || upper(r.statut)==='BROUILLON_CREE');
  text = `✉️ Brouillons Gmail (${list.length})\n\n` + (list.slice(0,10).map(line).join('\n\n') || 'Aucun brouillon créé.');
} else {
  text='Commande de consultation inconnue.';
}

if (text.length > 3900) text = text.slice(0,3890) + '\n…';
return [{json:{chat_id,telegram_message:text}}];

return $input.all().map(i=>({json:{
  ...i.json,
  chat_id:String(i.json.chat_id||''),
  telegram_message:String(i.json.telegram_message||'Mission reçue.')
}}));

const store=$getWorkflowStaticData('global');
const chat_id=String(store.telegram_chat_id||'');
if(!chat_id) return [];

const rows=$input.all().map(i=>i.json).filter(r=>r&&Object.keys(r).length);
const val=s=>String(s??'').trim();
const up=s=>val(s).toUpperCase();
const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const stamp=x=>{const t=Date.parse(val(x));return Number.isFinite(t)?t:0;};
