const recent=rows.filter(r=>stamp(r.derniere_mise_a_jour)&&now-stamp(r.derniere_mise_a_jour)<=day)
 .sort((a,b)=>stamp(b.derniere_mise_a_jour)-stamp(a.derniere_mise_a_jour));
const c=s=>rows.filter(r=>up(r.statut)===s).length;
const blocked=rows.filter(r=>up(r.statut).startsWith('BLOQUE')||up(r.statut)==='A_VERIFIER_DECES').length;
const rejectedDomains=rows.filter(r=>up(r.statut)==='REJETE_DOMAINE_GRAND_PUBLIC').length;
const drafts=rows.filter(r=>val(r.draft_id)||up(r.statut)==='BROUILLON_CREE').length;
const line=r=>`• ${esc(val(r.auteur)||'Auteur inconnu')} — ${esc(val(r.livre)||'Livre inconnu')} (${esc(val(r.statut)||'SANS_STATUT')})`;

let text=`📊 Rapport quotidien Impacteur

Activité 24 h : ${recent.length}
À vérifier : ${c('A_VERIFIER')}
YouTube à qualifier : ${c('YOUTUBE_A_QUALIFIER')}
À corriger : ${c('A_CORRIGER')}
Bloqués : ${blocked}
Approuvés : ${c('APPROUVE')}
Brouillons : ${drafts}\nRejets domaine grand public : ${rejectedDomains}

Dernières activités :
${recent.slice(0,8).map(line).join('\n')||'Aucune nouvelle activité.'}`;

if(text.length>3900) text=text.slice(0,3890)+'\n…';
return [{json:{chat_id,telegram_message:text}}];

const cfg=$('CONFIG - thèmes et chaîne').first().json;
const chat_id=String(cfg.telegram_chat_id||'');
if(!chat_id) return [];
const rows=$input.all().map(i=>i.json).filter(r=>r&&Object.keys(r).length);
const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const line=r=>`• ${esc(r.auteur||'Auteur inconnu')} — ${esc(r.livre||'Livre inconnu')} (${esc(r.statut||'enregistré')})`;
let text=`✅ Mission Telegram terminée.

Recherche : ${esc(cfg.recherche)}
Chaîne : ${esc(cfg.chaine)}
Dossiers enregistrés : ${rows.length}

${rows.slice(0,6).map(line).join('\n') || 'Aucun dossier enregistré.'}`;
if(text.length>3900) text=text.slice(0,3890)+'\n…';
return [{json:{chat_id,telegram_message:text}}];

