const chat_id=String(cfg.telegram_chat_id||first.telegram_chat_id||'');
if(!chat_id) return [];
return [{json:{
  chat_id,
  telegram_message:'⚠️ TRI EDITORIAL INCOMPLET\n\n'+String(first._editorial_warning||'').slice(0,2800)+'\n\nLa mission continue uniquement avec les candidats explicitement validés ; les autres sont écartés par sécurité.'
}}];

const req=$('TELEGRAM - analyser message').first().json;
const cle=String(req.cle_unique||'').trim();
const rows=$input.all().map(i=>i.json);
const row=rows.find(r=>String(r.cle_unique||'').trim()===cle);
const chat_id=String(req.chat_id||'');

if(!row){
  return [{json:{debloquer_ok:false,chat_id,telegram_message:'❌ Déblocage impossible : aucune fiche trouvée pour '+cle+'.'}}];
}

const statut=String(row.statut||'').trim().toUpperCase();
if(statut!=='A_VERIFIER_DECES'){
  return [{json:{
