const cfg=$('YOUTUBE - configurer recherche').first().json;
const results=$input.first().json.web?.results||[];
const videos=[];const ids=new Set();
for(const r of results){
 let u;try{u=new URL(String(r.url||''));}catch(e){continue;}
 if(!/(^|\.)youtube\.com$/i.test(u.hostname)||u.pathname!=='/watch')continue;
 const id=u.searchParams.get('v');
 if(!id||!/^[a-zA-Z0-9_-]{11}$/.test(id)||ids.has(id))continue;
 ids.add(id);
 videos.push({video_id:id,url:'https://www.youtube.com/watch?v='+id,title:String(r.title||'').slice(0,250),description:String(r.description||'').slice(0,700)});
