const cfg=$('YOUTUBE - préparer vidéos').first().json;
const histories=$('YOUTUBE - regrouper historique').first().json.historique||[];
const clean=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();
let data;try{
 const r=$input.first().json;
 if(r.stop_reason==='max_tokens')throw Error('Réponse tronquée');
 data=JSON.parse((r.content||[]).map(x=>x.text||'').join('\n').replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''));
 if(!Array.isArray(data.invites))throw Error('Format inattendu');
}catch(e){throw Error('YOUTUBE_IDENTIFICATION_TECHNIQUE : réponse Claude invalide.');}
const videos=new Map(cfg.videos.map(v=>[v.video_id,v]));
const existing=new Set(histories.filter(r=>/^https:\/\/(?:www\.)?youtube\.com\/watch\?v=/.test(String(r.source_livre||''))).map(r=>clean(r.auteur)).filter(Boolean));
const forbidden=new Set(histories.filter(r=>['NE_PAS_CONTACTER','REFUSE','OPPOSITION','BLOQUE_ELIGIBILITE','A_VERIFIER_DECES'].includes(String(r.statut||'').toUpperCase())).map(r=>clean(r.auteur)));
const seen=new Set();const output=[];
for(const e of data.invites){
 const v=videos.get(String(e.video_id||''));const name=String(e.nom||'').trim();const norm=clean(name);
 if(!v||e.confiance!=='FORTE'||name.split(/\s+/).length<2||name.length>100||!norm||seen.has(norm)||existing.has(norm)||forbidden.has(norm))continue;
 const context=clean(v.title+' '+v.description);
 if(!context.includes(norm))continue;
 seen.add(norm);
 const book=histories.find(r=>clean(r.auteur)===norm&&/^https:\/\/(?:[a-z]{2}\.)?welib\.st\//i.test(String(r.source_livre||'')));
 const topic=String(e.theme||'').slice(0,180);
 const alerts=['SOURCE_YOUTUBE : invité déduit du titre/description, identité, contenu et disponibilité à vérifier sur la vidéo.','VIDEO : '+v.url,'THEME_PROPOSE : '+topic,'AUCUN_CONTACT_AUTORISE : vérification humaine et invitation distincte nécessaires.'];
 if(book)alerts.push('CROISEMENT_WELIB : '+String(book.source_livre));
 output.push({json:{
  cle_unique:'yt:'+v.video_id,auteur:name,livre:'',editeur:'',date_publication:'',source_livre:v.url,
  description_livre:('Interview YouTube : '+v.title+' — '+v.description).slice(0,1600),chaine:cfg.chaine,
  recherches_auteur:'',recherches_editeur:'',emails_candidats:'',sources_contacts:'',
  objet_auteur:'',message_auteur:'',objet_editeur:'',message_editeur:'',
  informations_a_verifier:JSON.stringify(alerts),email_contact:'',type_contact:'',source_contact_validee:'',
  validation_contact:'NON',statut:'YOUTUBE_A_QUALIFIER',draft_id:'',derniere_mise_a_jour:new Date().toISOString()
 },pairedItem:{item:0}});
 if(output.length>=Math.max(1,Math.min(10,Number(cfg.max_invites)||5)))break;
}
return output;

// Convertit la réponse SRU Dublin Core de la BnF au format Google Books
// attendu par SELECTIONNER LIVRES ({items:[{id, volumeInfo:{...}}]}).
// Pré-filtres intégrés : texte imprimé uniquement, français, auteur personne
// physique, et exclusion immédiate si l'année de décès figure déjà dans la
// notice BnF ("(1937-2022)") — économise Brave et Claude en aval.
const decode = s => String(s || '')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
  .replace(/&#(\d+);/g, (m, d) => String.fromCharCode(Number(d)))
  .replace(/\s+/g, ' ').trim();

const items = [];
const seen = new Set();

for (const page of $input.all()) {
  const xml = String(page.json.data ?? page.json.body ?? '');
  if (!xml.includes('searchRetrieveResponse')) {
    throw new Error('Réponse BnF SRU inattendue : vérifier le nœud HTTP BNF.');
  }
  const recs = xml.match(/<srw:record>[\s\S]*?<\/srw:record>/g) || [];
  for (const rec of recs) {
    const field = name => {
      const m = rec.match(new RegExp('<dc:' + name + '[^>]*>([\\s\\S]*?)</dc:' + name + '>'));
      return m ? decode(m[1]) : '';
    };
    const fields = name => {
      const out = []; const re = new RegExp('<dc:' + name + '[^>]*>([\\s\\S]*?)</dc:' + name + '>', 'g');
      let m; while ((m = re.exec(rec))) out.push(decode(m[1]));
      return out;
    };

    const types = fields('type').join(' | ').toLowerCase();
    if (!/texte imprim|printed text/.test(types)) continue;         // pas de périodiques, images, etc.
    const langs = fields('language');
    if (langs.length && !langs.includes('fre')) continue;

    const creators = fields('creator');
    let creator = creators.find(c => /auteur du texte/i.test(c)) || creators[0] || '';
    if (!creator) continue;
    if (/\((\d{4})[-–](\d{4})\)/.test(creator)) continue;      // année de décès dans la notice -> exclu
    let nom = creator.replace(/\(.*$/, '').trim();
    // Retire la fonction BnF ("Mouré, Stéphane. Auteur du texte" -> "Mouré, Stéphane")
    nom = nom.replace(/\.\s*(auteur|autrice|directeur|directrice|editeur|éditeur|redacteur|rédacteur|traducteur|traductrice|prefacier|préfacier|postfacier|illustrateur|illustratrice|photographe|collaborateur|commentateur|annotateur)[\s\S]*$/i, '');
    nom = nom.trim().replace(/[.,;]+$/, '').trim();
    const parts = nom.split(',');
    if (parts.length >= 2) nom = (parts[1].trim() + ' ' + parts[0].trim()).trim();
    if (!nom) continue;

    const ark = (rec.match(/<srw:recordIdentifier>([\s\S]*?)<\/srw:recordIdentifier>/) || [])[1];
    const id = decode(ark || '');
    if (!id || seen.has(id)) continue;
    seen.add(id);

    let titre = field('title').split(' / ')[0].trim();
    // Certains titres BnF embarquent les auteurs sans séparateur " / " :
    // "La communication politique (5e éd.) Jacques Gerstlé, Christophe Piar"
    if (nom) {
      const pos = titre.indexOf(nom);
      if (pos > 3) titre = titre.slice(0, pos).replace(/[\s,;:/-]+$/, '').trim();
    }
    if (!titre) continue;
    const editeur = field('publisher').replace(/\s*\([^)]*\)\s*$/, '').trim();
    const sujets = fields('subject');
    const description = [field('description'), sujets.join(', ')].filter(Boolean).join(' — ');

    items.push({
      id,
      volumeInfo: {
        title: titre,
        subtitle: '',
        authors: [nom],
        publisher: editeur,
        publishedDate: field('date'),
        language: 'fr',
        description: description.slice(0, 1600),
        categories: sujets.slice(0, 6),
        infoLink: 'https://catalogue.bnf.fr/' + id
      }
    });
  }
}
return [{ json: { items, source_moteur: 'bnf_sru' }, pairedItem: { item: 0 } }];
